@MainActor
final class GuideScreen {
    var selectedID = 21
    private(set) var text = "Загрузка"
    func load(using fetch: (Int) async throws -> String) async throws {
        let requestedID = selectedID
        let value = try await fetch(requestedID)
        try Task.checkCancellation()
        guard selectedID == requestedID else { return }
        text = value
    }
}

При смене выбора старый ответ пропускается. Для неизменного выбора text получает результат.
